import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"通用","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/general.md","filePath":"zh-CN/user-guide/settings/general.md","lastUpdated":1784477413000}'),s={name:"zh-CN/user-guide/settings/general.md"};function n(i,t,l,g,p,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h1><p>四个 Tab:<strong>系统</strong>、<strong>搜索栏布局</strong>、<strong>预览窗口</strong>、<strong>搜索窗口</strong>。</p><h2 id="系统" tabindex="-1">系统 <a class="header-anchor" href="#系统" aria-label="Permalink to &quot;系统&quot;">​</a></h2><ul><li><strong>开机自动启动 SwiftList</strong> —— 复选框，登录时自动启动。</li><li><strong>启动时自动检查更新</strong> —— 复选框。</li><li><strong>自动静默更新</strong> —— 复选框，仅在上面的选项开启时可用；检测到新版本时在后台静默下载安装，不弹 窗提示。</li><li><strong>启用硬件加速</strong> —— 复选框，默认开启。关闭后会让快速搜索窗口改用软件渲染而不是 Direct3D——用 来解决 NVIDIA Advanced Optimus 因为 SwiftList 在运行而拒绝切换显卡的问题(只影响快速窗口，不影 响整个 App)。需要重启 SwiftList 才能生效。</li><li><strong>隐藏托盘图标</strong> —— 复选框，默认关闭。立即生效，不需要重启。不管这个设置开不开，快速窗口右上 角那个菜单按钮(☰)始终能打开和托盘图标右键一样的菜单(显示主窗口、切换热键、设置、关于、干净退 出、退出)，所以隐藏托盘图标不会让你找不到设置或退出的入口。菜单里的&quot;显示主窗口&quot;还会带上你当前 输入框里的搜索内容。</li><li><strong>日志等级</strong> —— 下拉框:错误 / 警告 / 信息(默认)/ 调试。控制 App、Service、Hook 三处日志(见 <a href="./service-status.html">运行状态</a>)的详细程度。</li><li><strong>界面语言</strong> —— 下拉框，内容来自所有已安装的语言包提供者(内置语言加上任何插件新增的语言)。</li></ul><p>主题选择已经移到独立的<a href="./appearance.html">外观</a>分区——主题选择器和&quot;跟随系统浅色/深色设置&quot;选项都在 那一页。</p><h2 id="搜索栏布局" tabindex="-1">搜索栏布局 <a class="header-anchor" href="#搜索栏布局" aria-label="Permalink to &quot;搜索栏布局&quot;">​</a></h2><p>自定义快速搜索栏的大小、圆角以及屏幕显示位置:</p><ul><li><strong>搜索栏宽度(像素)</strong> —— 范围 300–1200px，默认 570px。</li><li><strong>搜索栏高度(像素)</strong> —— 范围 45–120px，默认 60px。这一个数值同时驱动结果行的图标大小、名称/ 路径字体大小和行高(<code>高度 / 60</code>)，所以搜索栏调高，整个结果列表也会跟着放大，图标和文字始终保持 同样的比例。</li><li><strong>圆角半径(像素)</strong> —— 范围 0–50px，默认 8px。</li><li><strong>搜索框内显示时钟</strong> —— 复选框，默认关闭。开启后，当搜索框为空时会用当前日期、星期几和时间替 换掉原本的&quot;输入以搜索...&quot;提示文字。一开始输入内容，时钟就会和提示文字一样消失。只影响快速窗 口——内联窗口不管这个设置开没开，都保持它自己原本的提示文字。</li><li><strong>重置布局设置</strong> 按钮 —— 把以上四项都恢复为默认值。</li></ul><p>在快速窗口搜索框里的状态图标上右键，可以单独重置它的屏幕位置(不影响大小)，效果和首次启动时的 居中方式一样。</p><h2 id="预览窗口" tabindex="-1">预览窗口 <a class="header-anchor" href="#预览窗口" aria-label="Permalink to &quot;预览窗口&quot;">​</a></h2><ul><li><strong>预览窗口宽度(像素)</strong> —— 范围 250–900px。</li><li><strong>预览窗口高度(像素)</strong> —— 范围 250–1200px，默认值不会在常见显示器上显得过高。</li><li><strong>重置预览窗口设置</strong> 按钮。</li></ul><p>预览窗口的尺寸是固定的，不受当前结果数量影响——它不是一个随内容变化的自适应大小。预览面板具体如 何定位，见<a href="./../actions-and-preview.html">动作菜单与预览</a>。</p><h2 id="搜索窗口" tabindex="-1">搜索窗口 <a class="header-anchor" href="#搜索窗口" aria-label="Permalink to &quot;搜索窗口&quot;">​</a></h2><p>设置完整/主搜索窗口(从任务栏或开始菜单快捷方式打开的那个更大的窗口，区别于快速弹出搜索栏——见 <a href="./../getting-started.html#三种窗口">快速上手</a>)的默认大小:</p><ul><li><strong>窗口宽度(像素)</strong> —— 范围 640–2000px，默认 854px。</li><li><strong>窗口高度(像素)</strong> —— 范围 400–1400px，默认 480px。这两个下限分别对应窗口自身可拖拽调整的最 小尺寸，所以配置的值不会被窗口自己悄悄覆盖。</li><li><strong>重置搜索窗口设置</strong> 按钮。</li></ul><p>手动拖拽窗口边缘调整大小时会自动记住这个尺寸——下次打开窗口(或新开一个)时会沿用上次离开时的大 小，本页面上的数值也会同步更新。在窗口处于最大化状态时调整不会覆盖已记住的尺寸，只有在正常(非最 大化)状态下调整才会被记住。</p>',16)])])}const c=r(s,[["render",n]]);export{u as __pageData,c as default};
